    FROM c_cols
    WHERE `category` = 'Food'
)
SELECT * FROM c_rows;

WITH t_join AS (
    SELECT b.`category`, b.`amount`, e.`cost`
    FROM c_rows b
    LEFT JOIN expense e ON b.`category` = e.`expense_description`
)
SELECT * FROM t_join;

WITH t_sum AS (
    SELECT SUM(`amount`) AS total_amount, SUM(`cost`) AS total_cost
    FROM t_join
)
SELECT * FROM t_sum;

WITH final_cte AS (
    SELECT `total_amount` - COALESCE(`total_cost`, 0) AS remaining
    FROM t_sum
)
SELECT * FROM final_cte;

